--
-- Table structure for table `writing_attempts`
--

CREATE TABLE `writing_attempts` (
  `writing_attempt_id` bigint(20) UNSIGNED NOT NULL,
  `writing_session_id` bigint(20) UNSIGNED NOT NULL,
  `question_id` int(11) DEFAULT NULL,
  `template_character_id` int(3) NOT NULL,
  `target_character` varchar(10) NOT NULL,
  `romaji` varchar(50) NOT NULL DEFAULT '',
  `sequence_no` smallint(5) UNSIGNED NOT NULL,
  `image_file` varchar(255) NOT NULL,
  `trajectory_json` longtext DEFAULT NULL,
  `time_spent_ms` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `stroke_count` smallint(5) UNSIGNED NOT NULL DEFAULT 0,
  `shape_accuracy` decimal(5,2) DEFAULT 0.00,
  `position_accuracy` decimal(5,2) DEFAULT 0.00,
  `average_score` decimal(5,2) DEFAULT 0.00,
  `is_completed` tinyint(1) NOT NULL DEFAULT 1,
  `is_passed` tinyint(1) DEFAULT 0,
  `completed_at` datetime NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

