  `stroke_order_score` decimal(5,2) NOT NULL DEFAULT 0.00,
  `shape_accuracy_score` decimal(5,2) NOT NULL DEFAULT 0.00,
  `alignment_score` decimal(5,2) NOT NULL DEFAULT 0.00,
  `start_position_score` decimal(5,2) NOT NULL DEFAULT 0.00,
  `stroke_count_score` decimal(5,2) NOT NULL DEFAULT 0.00,
  `completeness_score` decimal(5,2) NOT NULL DEFAULT 0.00,
  `total_score` decimal(5,2) NOT NULL DEFAULT 0.00,
  `is_passed` tinyint(1) NOT NULL DEFAULT 0,
  `feedback` text DEFAULT NULL,
  `error_reasons` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`error_reasons`)),
  `ai_explanation` text DEFAULT NULL,
  `raw_result` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`raw_result`)),
  `evaluation_status` varchar(20) NOT NULL DEFAULT 'completed',
  `evaluated_at` datetime NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

