--
-- Table structure for table `writing_character_mastery`
--

CREATE TABLE `writing_character_mastery` (
  `mastery_id` bigint(20) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL,
  `character_id` int(11) NOT NULL,
  `total_attempts` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `successful_attempts` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `mastery_score` decimal(5,2) NOT NULL DEFAULT 0.00,
  `mastery_level` varchar(20) NOT NULL DEFAULT 'new',
  `is_remembered` tinyint(1) NOT NULL DEFAULT 0,
  `last_score` decimal(5,2) NOT NULL DEFAULT 0.00,
  `last_feedback` text DEFAULT NULL,
  `last_practiced_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

