--
-- Table structure for table `writing_quiz_questions`
--

CREATE TABLE `writing_quiz_questions` (
  `question_id` int(11) NOT NULL,
  `quiz_set_id` int(11) NOT NULL,
  `character_id` int(11) NOT NULL,
  `target_character` varchar(10) DEFAULT NULL,
  `target_romaji` varchar(50) DEFAULT NULL,
  `expected_stroke_count` smallint(5) UNSIGNED DEFAULT NULL,
  `difficulty_level` varchar(20) NOT NULL DEFAULT 'normal',
  `position_tolerance` decimal(5,2) NOT NULL DEFAULT 20.00,
  `stroke_order_required` tinyint(1) NOT NULL DEFAULT 1,
  `live_feedback_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `memory_check_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `feedback_beginner` text DEFAULT NULL,
  `feedback_intermediate` text DEFAULT NULL,
  `feedback_advanced` text DEFAULT NULL,
  `analysis_profile` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`analysis_profile`)),
  `sequence_no` int(11) DEFAULT 1,
  `max_score` decimal(5,2) DEFAULT 5.00,
  `question_text` varchar(255) DEFAULT 'จงเขียนตัวอักษรให้ถูกต้อง',
  `created_by_admin_id` int(11) DEFAULT NULL,
  `updated_by_admin_id` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `writing_quiz_sets`
--

CREATE TABLE `writing_quiz_sets` (
  `quiz_set_id` int(11) NOT NULL,
  `title` varchar(150) NOT NULL,
  `description` text DEFAULT NULL,
  `group_id` int(11) DEFAULT NULL,
  `order_type` enum('sequential','random') DEFAULT 'sequential',
  `pass_score` int(11) DEFAULT 80,
  `time_limit_seconds` int(11) DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `created_by_admin_id` int(11) NOT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Table structure for table `writing_sessions`
--

CREATE TABLE `writing_sessions` (
  `writing_session_id` bigint(20) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL,
  `quiz_set_id` int(11) DEFAULT NULL,
  `writing_type` varchar(20) NOT NULL,
  `group_name` varchar(100) NOT NULL DEFAULT '',
  `practice_mode` varchar(20) NOT NULL DEFAULT 'guide',
  `writing_mode` varchar(20) NOT NULL DEFAULT 'assisted',
  `started_at` datetime NOT NULL DEFAULT current_timestamp(),
  `completed_at` datetime DEFAULT NULL,
  `total_time_ms` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `total_characters` smallint(5) UNSIGNED NOT NULL DEFAULT 0,
  `completed_characters` smallint(5) UNSIGNED NOT NULL DEFAULT 0,
  `score` int(11) DEFAULT 0,
  `max_score` int(11) DEFAULT 5,
  `score_percentage` decimal(5,2) DEFAULT 0.00,
  `evaluation_status` varchar(50) DEFAULT 'ควรปรับปรุงเพิ่มเติม',
  `overall_shape_accuracy` decimal(5,2) DEFAULT 0.00,
  `overall_position_accuracy` decimal(5,2) DEFAULT 0.00
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

