--

CREATE TABLE `writing_svg_answer_references` (
  `svg_reference_id` bigint(20) UNSIGNED NOT NULL,
  `character_id` int(11) NOT NULL,
  `version_name` varchar(100) NOT NULL DEFAULT 'default',
  `variant_style` varchar(50) NOT NULL DEFAULT 'auto',
  `svg_file` varchar(255) DEFAULT NULL,
  `glif_file` varchar(255) DEFAULT NULL,
  `glif_content` longtext DEFAULT NULL,
  `svg_content` longtext DEFAULT NULL,
  `view_box` varchar(100) NOT NULL DEFAULT '0 0 620 420',
  `trajectory_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`trajectory_json`)),
  `stroke_count` smallint(5) UNSIGNED NOT NULL,
  `canvas_width` smallint(5) UNSIGNED NOT NULL DEFAULT 620,
  `canvas_height` smallint(5) UNSIGNED NOT NULL DEFAULT 420,
  `shape_tolerance` decimal(6,3) NOT NULL DEFAULT 0.250,
  `position_tolerance` decimal(6,3) NOT NULL DEFAULT 0.200,
  `require_stroke_order` tinyint(1) NOT NULL DEFAULT 1,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(10) UNSIGNED DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

